mrb_value
clone_mrb_obj(mrb_state *mrb, mrb_value self)
{
  mrb_value result;

  if (mrb_immediate_p(self)) {
    mrb_raise(mrb, E_TYPE_ERROR, "can't clone immediate value");
  }
  if (mrb_class_defined(mrb, "Class") && mrb_obj_is_instance(mrb_class(mrb), self)) {
    mrb_raise(mrb, E_TYPE_ERROR, "can't clone class");
  }

  result = mrb_obj_new(mrb, mrb_obj_class(self), 0, NULL);
  mrb_data_object_dup(mrb, result, self);

  if (mrb_obj_singleton_class_p(self)) {
    mrb_value sc = mrb_get_singleton_class(self);
    mrb_set_singleton_class(result, sc);
  }

  if (mrb_obj_frozen_p(self)) {
    mrb_obj_freeze(mrb, result);
  }

  return result;
}

mrb_value
mrb_clone(mrb_state *mrb, mrb_value self)
{
  mrb_value clone;
  mrb_obj* obj;

  if (mrb_immediate_p(self)) {
    mrb_raise(mrb, E_TYPE_ERROR, "can't clone IMMEDIATE");
  }
  if (mrb_singleton_class_p(mrb_obj_class(self))) {
    mrb_raise(mrb, E_TYPE_ERROR, "can't clone singleton class");
  }

  obj = mrb_obj_alloc(mrb, mrb_class(self), mrb_obj_class(self));
  clone = mrb_obj_value(obj);
  mrb_set_singleton_class(clone, mrb_dup_singleton_class(mrb, self));

  mrb_copy_object(mrb, obj, mrb_obj_ptr(self));
  if (mrb_obj_frozen(self)) {
    mrb_obj_freeze(mrb, clone);
  }

  return clone;
}

mrb_value
mrb_clone(mrb_state *mrb, mrb_value self)
{
  mrb_value clone;
  mrb_obj_clone(mrb, self, clone);
  return clone;
}

mrb_value
mrb_obj_clone(mrb_state *mrb, mrb_value self)
{
  mrb_value c;

  if (mrb_immediate_p(self)) {
    mrb_raise(mrb, E_TYPE_ERROR, "can't clone immediate value");
  }
  if (mrb_singleton_class(mrb, self)) {
    mrb_raise(mrb, E_TYPE_ERROR, "can't clone singleton class");
  }

  c = mrb_obj_dup(mrb, self);
  if (mrb_obj_singleton_class_p(self)) {
    mrb_value sc = mrb_obj_singleton_class(mrb, self);
    mrb_value nsc = mrb_make_singleton_class(mrb, c);
    mrb_obj_clone_ivar(mrb, nsc, sc);
  }
  mrb_obj_set_flag(mrb, c, MRB_FL_USER1 | MRB_FL_USER2);
  if (mrb_obj_frozen_p(self)) {
    mrb_obj_freeze(mrb, c);
  }
  return c;
}

mrb_value
mrb_clone(mrb_state *mrb, mrb_value self)
{
  mrb_value cloned;

  if (mrb_immediate_p(self)) {
    mrb_raise(mrb, E_TYPE_ERROR, "can't clone immediate value");
  }

  if (mrb_obj_singleton_class_p(self)) {
    mrb_raise(mrb, E_TYPE_ERROR, "can't clone singleton class");
  }

  cloned = mrb_obj_alloc(mrb, mrb_class(self), mrb_module(self));
  mrb_data_object_dup(mrb, cloned, self);

  if (mrb_obj_singleton_class_p(cloned)) {
    mrb_raise(mrb, E_TYPE_ERROR, "can't clone singleton class");
  }

  if (mrb_obj_frozen_p(self)) {
    mrb_obj_freeze(mrb, cloned);
  }

  return cloned;
}
